    // Warmup
    for (int i = 0; i < warmupIters; i++)
        action();

    // Measure multiple rounds for statistical stability
    const int rounds = 5;
    double[] msPerOp = new double[rounds];
    int itersPerRound = measuredIters / rounds;

    for (int r = 0; r < rounds; r++)
    {
