        GC.WaitForPendingFinalizers();
        GC.Collect();

        var sw = Stopwatch.StartNew();
        for (int i = 0; i < itersPerRound; i++)
            action();
        sw.Stop();
        msPerOp[r] = sw.Elapsed.TotalMilliseconds / itersPerRound;
